package server

import (
	"html"
	"io"
	"net/http"
	"os"
	"strings"
)

const catalogPageCSS = `
*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#06170d;color:#ecfff0}button,input,select{font:inherit}button{cursor:pointer}.app{min-height:100vh;display:grid;grid-template-columns:250px 1fr}.side{position:sticky;top:0;height:100vh;padding:28px 18px;background:#0a2112;border-right:1px solid #24432e;display:flex;flex-direction:column}.brand{font:28px Georgia,serif;color:#fff;margin:0 8px 30px}.navbtn,.folderbtn{width:100%;display:flex;align-items:center;justify-content:space-between;border:0;background:transparent;color:#b9d6c0;padding:10px 12px;border-radius:10px;text-align:left}.navbtn:hover,.folderbtn:hover,.navbtn.active,.folderbtn.active{background:#173a22;color:#fff}.count{font-size:11px;color:#789882}.folders-head{display:flex;justify-content:space-between;align-items:center;margin:26px 10px 8px;color:#789882;text-transform:uppercase;letter-spacing:.12em;font-size:11px}.iconbtn{border:0;background:transparent;color:#9bc6a6;padding:4px 7px;border-radius:7px}.iconbtn:hover{background:#21472b;color:#fff}.folderrow{display:flex;align-items:center}.folderrow .folderbtn{flex:1}.folderlist{min-height:0;overflow:auto}.docslink{margin-top:auto;display:flex;align-items:center;justify-content:space-between;gap:12px;color:#b9d6c0;text-decoration:none;padding:15px 12px 2px;border-top:1px solid #24432e;font-size:13px}.docslink:hover{color:#fff}.docslink span:last-child{color:#71ee8b}.content{padding:34px clamp(22px,4vw,64px);min-width:0}.top{display:flex;align-items:center;justify-content:space-between;gap:18px}.top h1{font:42px Georgia,serif;font-weight:400;margin:0;color:#fff}.account{display:flex;align-items:center;gap:14px;color:#9bc6a6}.account a{color:#8ef6a6}.secondary,.primary{border-radius:10px;padding:9px 13px;border:1px solid #41614a;font-weight:700}.primary{background:#71ee8b;color:#06170d;border-color:#71ee8b}.secondary{background:transparent;color:#def6e3}.tools{display:grid;grid-template-columns:minmax(220px,1fr) auto auto;gap:10px;margin:28px 0 18px}.tools input,.tools select,dialog input,dialog select{background:#f7fff8;color:#102516;border:1px solid #789882;border-radius:10px;padding:11px 13px}.bulk{display:none;align-items:center;gap:10px;padding:10px 12px;border-radius:12px;background:#14351f;margin-bottom:14px}.bulk.on{display:flex}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:16px}.card{position:relative;min-height:230px;background:linear-gradient(150deg,#153c22,#0d2817);border:1px solid #31543a;border-radius:17px;padding:18px;display:flex;flex-direction:column;transition:.16s transform,.16s border-color,.16s box-shadow}.card:hover{transform:translateY(-2px);border-color:#65dc81;box-shadow:0 16px 40px #0005}.card.selected{outline:2px solid #71ee8b}.card.dragging{opacity:.5}.preview{height:88px;border-radius:11px;background:radial-gradient(circle at 75% 25%,#71ee8b33,transparent 30%),linear-gradient(130deg,#0b2414,#1b4e2b);display:grid;place-items:center;color:#79aa85;font:22px Georgia,serif;margin-bottom:15px;overflow:hidden}.preview img{width:100%;height:100%;object-fit:cover}.card h3{font-size:18px;margin:0 28px 6px 0;color:#fff}.meta{font-size:12px;color:#88ad91;min-height:34px}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:auto;padding-top:15px}.actions button{font-size:12px;padding:7px 9px}.pick{position:absolute;top:17px;right:17px;width:19px;height:19px}.empty{display:none;padding:70px 20px;text-align:center;border:1px dashed #31543a;border-radius:16px;color:#83a88c}.empty.on{display:block}.toast{position:fixed;right:24px;bottom:24px;background:#eefcf1;color:#102516;padding:13px 17px;border-radius:11px;box-shadow:0 12px 45px #0008;transform:translateY(120px);opacity:0;transition:.2s;z-index:20}.toast.on{transform:none;opacity:1}dialog{width:min(760px,calc(100vw - 30px));max-height:85vh;overflow:auto;background:#102f1b;color:#effff2;border:1px solid #41614a;border-radius:18px;padding:24px}dialog::backdrop{background:#000b}.dialoghead{display:flex;align-items:center;justify-content:space-between}.slidegrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:9px;margin:16px 0}.slidepick{display:flex;gap:9px;align-items:flex-start;padding:12px;background:#183c23;border-radius:10px}.transferopts{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:18px 0}.dropover{outline:2px dashed #71ee8b;outline-offset:-4px}@media(max-width:760px){.app{display:block}.side{position:static;height:auto;border:0;padding:17px}.brand{margin-bottom:12px}.side nav,.folderlist{display:flex;gap:6px;overflow:auto}.navbtn,.folderbtn{width:auto;white-space:nowrap}.folders-head{display:none}.docslink{margin-top:15px;padding:13px 8px 0}.content{padding:22px 16px}.top h1{font-size:34px}.tools{grid-template-columns:1fr 1fr}.tools input{grid-column:1/-1}.grid{grid-template-columns:1fr}.account span{display:none}}
`

func documentationURL() string {
	if configured := strings.TrimSpace(os.Getenv("VSTD_DOCS_URL")); configured != "" {
		return configured
	}
	return "https://vessica-studio-docs-production.up.railway.app"
}

func (s *Server) renderCatalogPage(w http.ResponseWriter, userName, role, csrf string, collaboration bool) {
	teamLink := ""
	logout := ""
	if collaboration {
		if role == "owner" {
			teamLink = `<a href="/team">Team</a>`
		}
		logout = `<button class="secondary" id="logout">Log out</button>`
	}
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	io.WriteString(w, `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Presentations · Vessica Studio</title><style>`+catalogPageCSS+`</style></head><body><div class="app"><aside class="side"><div class="brand">Vessica Studio</div><nav id="views"></nav><div class="folders-head"><span>Folders</span><button class="iconbtn" id="addFolder" aria-label="Create folder">＋</button></div><div class="folderlist" id="folders"></div><a class="docslink" href="`+html.EscapeString(documentationURL())+`" target="_blank" rel="noopener noreferrer"><span>Documentation</span><span aria-hidden="true">↗</span></a></aside><main class="content"><header class="top"><div><h1 id="pageTitle">Presentations</h1><div class="meta">Signed in as `+html.EscapeString(userName)+`</div></div><div class="account">`+teamLink+logout+`</div></header><div class="tools"><input id="search" type="search" placeholder="Search presentations" aria-label="Search presentations"><select id="sort" aria-label="Sort presentations"><option value="recent">Recently opened</option><option value="alpha">Title A–Z</option><option value="owner">Owner</option></select><button class="primary" id="newDeck">New presentation</button></div><div class="bulk" id="bulk"><b id="selectedCount"></b><select id="bulkFolder" aria-label="Move selected presentations"></select><button class="primary" id="moveSelected">Move</button><button class="secondary" id="clearSelected">Clear</button></div><div class="grid" id="cards"></div><div class="empty" id="empty"><h2>Nothing here yet</h2><p>Create a presentation, move one into this folder, or try a different search.</p></div></main></div><div class="toast" id="toast" role="status" aria-live="polite"></div><dialog id="transferDialog"><div class="dialoghead"><div><h2>Send slides to another presentation</h2><div class="meta" id="transferSource"></div></div><button class="secondary" id="closeTransfer">Close</button></div><div class="slidegrid" id="slideChoices"></div><div class="transferopts"><label>Destination<br><select id="transferTarget"></select></label><fieldset><legend>Transfer type</legend><label><input type="radio" name="transferMode" value="copy" checked> Editable copy</label><br><label><input type="radio" name="transferMode" value="link"> Live linked snapshot</label></fieldset></div><button class="primary" id="submitTransfer">Send selected slides</button></dialog><script>
const csrf=`+strconvQuote(csrf)+`,collaboration=`+map[bool]string{true: "true", false: "false"}[collaboration]+`;let data={folders:[],decks:[]},view='all',folder='',selected=new Set(),transferDeck=null;const $=id=>document.getElementById(id),esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(path,method='GET',body){const o={method,headers:{}};if(method!=='GET'){o.headers['Content-Type']='application/json';if(csrf)o.headers['X-CSRF-Token']=csrf;o.body=JSON.stringify(body||{})}const r=await fetch(path,o),j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'HTTP '+r.status);return j}function say(msg){toast.textContent=msg;toast.classList.add('on');setTimeout(()=>toast.classList.remove('on'),2800)}function counts(){return{all:data.decks.length,mine:data.decks.filter(d=>d.owned).length,shared:data.decks.filter(d=>!d.owned).length,recent:data.decks.filter(d=>d.last_opened_at).length}}function renderSide(){const c=counts(),items=[['all','All presentations',c.all],['mine','My presentations',c.mine],['shared','Shared with me',c.shared],['recent','Recent',c.recent]];views.innerHTML=items.filter(x=>collaboration||x[0]!=='shared').map(x=>'<button class="navbtn '+(view===x[0]&&!folder?'active':'')+'" data-view="'+x[0]+'"><span>'+x[1]+'</span><span class="count">'+x[2]+'</span></button>').join('');folders.innerHTML=data.folders.map(f=>'<div class="folderrow" data-drop-folder="'+f.id+'"><button class="folderbtn '+(folder===f.id?'active':'')+'" data-folder="'+f.id+'"><span>📁 '+esc(f.name)+'</span><span class="count">'+f.count+'</span></button><button class="iconbtn" data-folder-menu="'+f.id+'" aria-label="Edit '+esc(f.name)+'">⋯</button></div>').join('');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;folder='';render()});document.querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>{folder=b.dataset.folder;view='all';render()});document.querySelectorAll('[data-folder-menu]').forEach(b=>b.onclick=()=>folderMenu(b.dataset.folder));wireDrops()}function visibleDecks(){let a=data.decks.filter(d=>!folder||d.folder_id===folder);if(!folder&&view==='mine')a=a.filter(d=>d.owned);if(!folder&&view==='shared')a=a.filter(d=>!d.owned);if(!folder&&view==='recent')a=a.filter(d=>d.last_opened_at);const q=search.value.trim().toLowerCase();if(q)a=a.filter(d=>(d.title+' '+d.storage_key+' '+(d.owner_name||'')).toLowerCase().includes(q));const by=sort.value;a.sort((x,y)=>by==='alpha'?x.title.localeCompare(y.title):by==='owner'?(x.owner_name||'').localeCompare(y.owner_name||''):(Date.parse(y.last_opened_at||0)-Date.parse(x.last_opened_at||0)||x.title.localeCompare(y.title)));return a}function card(d){const owner=d.owned?(d.visibility==='team'?'Shared with team':'Private'):('Shared by '+esc(d.owner_name||'teammate')+' · read only');const actions=d.owned?'<button class="primary" data-launch="edit">Edit</button><button class="secondary" data-launch="present">Present</button><button class="secondary" data-transfer>Send slides</button><button class="secondary" data-fork>Fork</button>'+(collaboration?'<button class="secondary" data-visibility>'+(d.visibility==='team'?'Make private':'Share with team')+'</button>':''):'<button class="primary" data-launch="view">View</button><button class="secondary" data-launch="present">Present</button><button class="secondary" data-transfer>Send slides</button><button class="secondary" data-fork>Fork</button>';return '<article class="card '+(selected.has(d.id)?'selected':'')+'" draggable="true" data-id="'+d.id+'"><input class="pick" type="checkbox" aria-label="Select '+esc(d.title)+'" '+(selected.has(d.id)?'checked':'')+'><div class="preview">'+esc((d.title||'V').slice(0,1))+'</div><h3>'+esc(d.title)+'</h3><div class="meta">'+esc(d.storage_key)+'<br>'+owner+'</div><div class="actions">'+actions+'</div></article>'}function renderCards(){const ds=visibleDecks();cards.innerHTML=ds.map(card).join('');empty.classList.toggle('on',!ds.length);document.querySelectorAll('.card').forEach(el=>{const d=data.decks.find(x=>x.id===el.dataset.id);el.querySelector('.pick').onchange=e=>{e.target.checked?selected.add(d.id):selected.delete(d.id);render()};el.querySelectorAll('[data-launch]').forEach(b=>b.onclick=()=>launch(d,b.dataset.launch));el.querySelector('[data-transfer]').onclick=()=>openTransfer(d);el.querySelector('[data-fork]').onclick=()=>forkDeck(d);const vb=el.querySelector('[data-visibility]');if(vb)vb.onclick=()=>visibility(d);el.ondragstart=()=>{el.classList.add('dragging');selected.add(d.id)};el.ondragend=()=>el.classList.remove('dragging')});selectedCount.textContent=selected.size+' selected';bulk.classList.toggle('on',selected.size>0);bulkFolder.innerHTML='<option value="">No folder</option>'+data.folders.map(f=>'<option value="'+f.id+'">'+esc(f.name)+'</option>').join('')}function render(){renderSide();renderCards();pageTitle.textContent=folder?(data.folders.find(f=>f.id===folder)||{}).name||'Folder':({all:'Presentations',mine:'My presentations',shared:'Shared with me',recent:'Recent'}[view])}async function launch(d,mode){const j=await api('/api/app/decks/'+d.id+'/launch','POST',{mode});location.href=j.url}async function visibility(d){await api('/api/app/decks/'+d.id+'/visibility','PATCH',{visibility:d.visibility==='team'?'private':'team'});say('Sharing updated');load()}async function forkDeck(d){const title=prompt('Name for the fork',d.title+' (copy)');if(!title)return;await api('/api/app/decks/'+d.id+'/fork','POST',{title});say('Presentation forked');load()}async function move(ids,to){if(!ids.length)return;await api('/api/app/decks/'+ids[0]+'/folder','PUT',{deck_ids:ids,folder_id:to});selected.clear();say('Presentation'+(ids.length>1?'s':'')+' moved');load()}function wireDrops(){document.querySelectorAll('[data-drop-folder]').forEach(row=>{row.ondragover=e=>{e.preventDefault();row.classList.add('dropover')};row.ondragleave=()=>row.classList.remove('dropover');row.ondrop=e=>{e.preventDefault();row.classList.remove('dropover');move([...selected],row.dataset.dropFolder)}})}async function folderMenu(id){const f=data.folders.find(x=>x.id===id),name=prompt('Rename folder. Leave empty to delete it.',f.name);if(name===null)return;if(!name.trim()){if(confirm('Delete “'+f.name+'”? Presentations will move to the root.')){await api('/api/app/folders/'+id,'DELETE');say('Folder deleted');folder='';load()}return}await api('/api/app/folders/'+id,'PATCH',{name});say('Folder renamed');load()}async function openTransfer(d,preselected=[]){transferDeck=d;const j=await api('/api/app/decks/'+d.id+'/slides');transferSource.textContent=d.title;slideChoices.innerHTML=j.slides.filter(s=>!s.parked).map(s=>'<label class="slidepick"><input type="checkbox" value="'+s.id+'" '+(preselected.includes(s.id)?'checked':'')+'><span><b>'+s.number+'. '+esc(s.title)+'</b><br><span class="meta">'+(s.linked?'Linked snapshot':'Slide')+'</span></span></label>').join('');transferTarget.innerHTML=data.decks.filter(x=>x.owned&&x.id!==d.id).map(x=>'<option value="'+x.id+'">'+esc(x.title)+'</option>').join('');submitTransfer.disabled=!transferTarget.options.length;transferDialog.showModal()}async function load(){data=await api('/api/app/catalog');render();const m=location.hash.match(/^#transfer=([A-Za-z0-9_-]+)$/);if(m){history.replaceState(null,'',location.pathname+location.search);const intent=await api('/api/app/slide-transfer-intents/exchange','POST',{token:m[1]}),d=data.decks.find(x=>x.id===intent.source_deck_id);if(!d)throw Error('Source presentation is no longer available');await openTransfer(d,intent.slide_ids)}}submitTransfer.onclick=async()=>{const ids=[...slideChoices.querySelectorAll('input:checked')].map(x=>x.value);if(!ids.length){say('Select at least one slide');return}const mode=document.querySelector('input[name=transferMode]:checked').value;const j=await api('/api/app/slide-transfers','POST',{source_deck_id:transferDeck.id,target_deck_id:transferTarget.value,slide_ids:ids,mode});transferDialog.close();say(j.slide_ids.length+' slide'+(j.slide_ids.length===1?'':'s')+' sent')};closeTransfer.onclick=()=>transferDialog.close();addFolder.onclick=async()=>{const name=prompt('Folder name');if(!name)return;await api('/api/app/folders','POST',{name});say('Folder created');load()};newDeck.onclick=async()=>{const title=prompt('Presentation title');if(!title)return;await api('/api/app/decks','POST',{title});say('Presentation created');load()};moveSelected.onclick=()=>move([...selected],bulkFolder.value);clearSelected.onclick=()=>{selected.clear();render()};search.oninput=renderCards;sort.onchange=renderCards;if($('logout'))logout.onclick=async()=>{await api('/api/auth/logout','POST',{});location.replace('/auth/login')};load().catch(e=>say(e.message));
</script><style>.preview{position:relative}.preview img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}</style><script>const thumbnailObserver=new MutationObserver(()=>document.querySelectorAll('.card .preview:not([data-thumbnail])').forEach(p=>{p.dataset.thumbnail='1';const card=p.closest('.card'),img=new Image();img.alt='';img.loading='lazy';img.src='/api/app/decks/'+encodeURIComponent(card.dataset.id)+'/thumbnail.png';img.onerror=()=>img.remove();p.appendChild(img)}));thumbnailObserver.observe(cards,{childList:true});</script></body></html>`)
}
